const root=document.querySelector('#mpquotes-view');let rows=[],selected=null;
const esc=v=>String(v??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
const statuses=['Solicitado','Em cotação','Aguardando aprovação','Pedido emitido','Aguardando entrega','Recebido / Concluído','Cancelado'];
const d=v=>v?v.split('-').reverse().join('/'):'—';
const parsed=r=>{try{return JSON.parse(r.quotesJson||'[]')}catch{return[]}};
const quotes=r=>parsed(r).filter(x=>x&&x.kind==='quote');
const num=v=>{let x=String(v??'').trim().replace(/R\$\s?/gi,'').replace(/\s/g,'');if(!x)return null;if(x.includes(','))x=x.replace(/\./g,'').replace(',','.');else if(/^\d+\.\d{1,2}$/.test(x)){}else x=x.replace(/\./g,'');const n=Number(x);return Number.isFinite(n)?n:null};
const money=v=>{const n=num(v);return n==null?'—':n.toLocaleString('pt-BR',{style:'currency',currency:'BRL'})};
const payScore=t=>{const x=String(t||'').toLowerCase();if(!x)return 40;if(/vista/.test(x))return 10;const ns=[...x.matchAll(/\d+/g)].map(m=>Number(m[0])).filter(n=>n>0);if(!ns.length)return 35;const avg=ns.reduce((a,b)=>a+b,0)/ns.length;return Math.min(100,Math.round(avg*2+Math.min(ns.length,4)*10))};
const deliveryScore=v=>{const n=Number(String(v||'').match(/\d+/)?.[0]);return Number.isFinite(n)?Math.max(10,100-n*4):50};
async function load(){const r=await fetch('/api/maintenance');const j=await r.json();rows=(j.requests||[]).filter(x=>x.category==='MP');render()}
async function removeRequest(r){if(!confirm('Excluir '+r.number+' · '+r.description+'?\n\nTodas as cotações desta solicitação também serão excluídas. Essa ação ficará registrada na Auditoria.'))return;const z=await fetch('/api/maintenance/'+encodeURIComponent(r.id),{method:'DELETE'}),j=await z.json();if(!z.ok)throw Error(j.error||'Erro ao excluir');await load()} 
async function save(r,patch){const v={...r,...patch,category:'MP',type:'Material'};delete v.history;delete v.createdAt;delete v.updatedAt;delete v.number;const z=await fetch('/api/maintenance',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(v)}),j=await z.json();if(!z.ok)throw Error(j.error||'Erro ao salvar');return j}
function card(r){const q=quotes(r),vals=q.map(x=>num(x.amount)).filter(x=>x!=null);return '<article class="mpq-card" data-open="'+r.id+'"><div><strong>'+esc(r.number)+'</strong><span>'+esc(r.status)+'</span></div><h4>'+esc(r.description)+'</h4><p>🏢 <b>Empresa:</b> '+esc(r.company||'—')+'</p><p>♙ <b>Solicitante:</b> '+esc(r.requester)+'</p><p>▣ <b>Responsável:</b> '+esc(r.buyer||'—')+'</p><p>⚖ <b>Quantidade:</b> '+esc(r.quantity||'—')+' '+esc(r.unit||'')+'</p><p>📅 <b>Necessário até:</b> '+d(r.neededDate)+'</p><div class="mpq-summary"><b>Cotações</b><br>'+q.length+' fornecedores'+(vals.length?'<br><em>Menor valor: '+money(Math.min(...vals))+'</em>':'')+'</div><div class="mpq-card-actions"><button title="Ver / cotar" data-detail="'+r.id+'">👁️</button><button title="Editar" data-mpedit="'+r.id+'">✏️</button><button title="Excluir solicitação" data-mpdelete="'+r.id+'">🗑️</button></div></article>'}
function render(){root.innerHTML='<div class="report-slot"></div><div class="mpq-top"><button id="mp-new">＋ Nova cotação de MP</button></div><div class="maintenance-kpis">'+[['Solicitado',rows.filter(x=>x.status==='Solicitado').length],['Em cotação',rows.filter(x=>x.status==='Em cotação').length],['Aguardando aprovação',rows.filter(x=>x.status==='Aguardando aprovação').length],['Pedido emitido',rows.filter(x=>x.status==='Pedido emitido').length],['Aguardando entrega',rows.filter(x=>x.status==='Aguardando entrega').length]].map(x=>'<div class="blue"><strong>'+x[1]+'</strong><span>'+x[0]+'</span></div>').join('')+'</div><section class="panel mpq-toolbar"><input id="mp-search" placeholder="Buscar matéria-prima, código ou fornecedor"><select id="mp-status"><option value="">Todos os status</option>'+statuses.map(x=>'<option>'+x+'</option>').join('')+'</select></section><div id="mp-editor"></div><div id="mp-list" class="mpq-grid"></div><div id="mp-detail"></div>';document.querySelector('#mp-new').onclick=()=>form({status:'Solicitado',origin:'Outro',priority:'Normal'});document.querySelector('#mp-search').oninput=draw;document.querySelector('#mp-status').onchange=draw;draw()}
function draw(){const q=document.querySelector('#mp-search').value.toLowerCase(),st=document.querySelector('#mp-status').value;const a=rows.filter(r=>(!q||JSON.stringify(r).toLowerCase().includes(q))&&(!st||r.status===st));document.querySelector('#mp-list').innerHTML=a.length?a.map(card).join(''):'<section class="panel"><p>Nenhuma cotação de matéria-prima encontrada.</p></section>';document.querySelectorAll('[data-detail]').forEach(b=>b.onclick=e=>{e.stopPropagation();detail(rows.find(r=>r.id===b.dataset.detail))});document.querySelectorAll('[data-mpedit]').forEach(b=>b.onclick=e=>{e.stopPropagation();form(rows.find(r=>r.id===b.dataset.mpedit))});document.querySelectorAll('[data-mpdelete]').forEach(b=>b.onclick=async e=>{e.stopPropagation();try{await removeRequest(rows.find(r=>r.id===b.dataset.mpdelete))}catch(x){alert(x.message)}});document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>detail(rows.find(r=>r.id===b.dataset.open)))}
function form(r){const box=document.querySelector('#mp-editor');box.innerHTML='<section class="panel maintenance-editor"><h3>'+(r.id?'Editar '+esc(r.number):'Nova cotação de matéria-prima')+'</h3><form id="mpf"><div class="maintenance-fields"><label>Empresa<select name="company"><option>Colafix</option><option>Fixcol</option><option>Argamazza</option><option>Cassaroli</option></select></label><label>Solicitante<input name="requester" required value="'+esc(r.requester||'')+'"></label><label>Responsável pela compra<input name="buyer" value="'+esc(r.buyer||'PAULO')+'"></label><label>Código do material<input name="oc" value="'+esc(r.oc||'')+'"></label><label>Quantidade<input name="quantity" value="'+esc(r.quantity||'')+'"></label><label>UN<input name="unit" value="'+esc(r.unit||'KG')+'"></label><label>Necessário até<input type="date" name="neededDate" value="'+esc(r.neededDate||'')+'"></label><label>Status<select name="status">'+statuses.map(x=>'<option'+(x===(r.status||'Solicitado')?' selected':'')+'>'+x+'</option>').join('')+'</select></label></div><label>Matéria-prima<textarea name="description" required>'+esc(r.description||'')+'</textarea></label><label>Observações<textarea name="notes">'+esc(r.notes||'')+'</textarea></label><button>Salvar</button> <button type="button" id="mp-close">Fechar</button><p id="mp-msg"></p></form></section>';box.scrollIntoView({behavior:'smooth',block:'start'});const f=document.querySelector('#mpf');if(r.company)f.company.value=r.company;document.querySelector('#mp-close').onclick=()=>box.innerHTML='';f.onsubmit=async e=>{e.preventDefault();const v=Object.fromEntries(new FormData(f));v.id=r.id;v.version=r.version;v.quotesJson=r.quotesJson||'[]';try{await save(r,v);await load()}catch(x){document.querySelector('#mp-msg').textContent=x.message}}}
function analysis(r){const q=quotes(r).filter(x=>num(x.amount)!=null);if(!q.length)return '<p>Cadastre valores para gerar a análise.</p>';const min=Math.min(...q.map(x=>num(x.amount)));const scored=q.map(x=>{const ps=Math.round(min/num(x.amount)*100),ds=deliveryScore(x.delivery),pays=payScore(x.payment);return {...x,ps,ds,pays,total:Math.round(ps*.4+ds*.3+pays*.3)}}).sort((a,b)=>b.total-a.total);const best=scored[0];return '<div class="mpq-analysis"><h3>RECOMENDAÇÃO DO SISTEMA</h3><h2>✓ '+esc(best.supplier)+'</h2><p>Melhor relação considerando preço, prazo de entrega e condição de pagamento.</p><div class="table-scroll"><table><thead><tr><th>Fornecedor</th><th>Preço</th><th>Entrega</th><th>Pagamento</th><th>Preço 40%</th><th>Entrega 30%</th><th>Pagamento 30%</th><th>Índice</th></tr></thead><tbody>'+scored.map(x=>'<tr'+(x===best?' class="mpq-best"':'')+'><td>'+esc(x.supplier)+'</td><td>'+money(x.amount)+'</td><td>'+esc(x.delivery||'A confirmar')+'</td><td>'+esc(x.payment||'A confirmar')+'</td><td>'+x.ps+'</td><td>'+x.ds+'</td><td>'+x.pays+'</td><td><b>'+x.total+'%</b></td></tr>').join('')+'</tbody></table></div></div>'}
function detail(r){selected=r.id;const q=quotes(r);const box=document.querySelector('#mp-detail');box.innerHTML='<section class="panel mpq-detail"><div class="mn-detail-head"><div><strong>'+esc(r.number)+'</strong> · '+esc(r.description)+'</div><button id="mp-edit">✏️ Editar solicitação</button></div><div class="mpq-info"><b>Empresa:</b> '+esc(r.company||'—')+' · <b>Quantidade:</b> '+esc(r.quantity||'—')+' '+esc(r.unit||'')+' · <b>Necessário:</b> '+d(r.neededDate)+'</div><h3>Cotações ('+q.length+')</h3><div class="table-scroll"><table><thead><tr><th>Fornecedor</th><th>Valor</th><th>Prazo entrega</th><th>Pagamento</th><th>Observação</th><th>Ações</th></tr></thead><tbody>'+(q.length?q.map((x,i)=>'<tr><td>'+esc(x.supplier)+'</td><td>'+money(x.amount)+'</td><td>'+esc(x.delivery||'—')+'</td><td>'+esc(x.payment||'—')+'</td><td>'+esc(x.notes||'—')+'</td><td><button data-qedit="'+i+'">✏️</button> <button data-qdel="'+i+'">🗑️</button></td></tr>').join(''):'<tr><td colspan="6">Nenhuma cotação cadastrada.</td></tr>')+'</tbody></table></div><button id="mp-addq">＋ Adicionar cotação</button><button id="mp-analyze">⚖ Analisar cotações</button><div id="mp-qform"></div><div id="mp-analysis"></div></section>';box.scrollIntoView({behavior:'smooth',block:'start'});document.querySelector('#mp-edit').onclick=()=>form(r);document.querySelector('#mp-addq').onclick=()=>quoteForm(r,null);document.querySelector('#mp-analyze').onclick=()=>document.querySelector('#mp-analysis').innerHTML=analysis(r);document.querySelectorAll('[data-qedit]').forEach(b=>b.onclick=()=>quoteForm(r,Number(b.dataset.qedit)));document.querySelectorAll('[data-qdel]').forEach(b=>b.onclick=async()=>{const i=Number(b.dataset.qdel);if(!confirm('Excluir cotação de '+q[i].supplier+'?'))return;await save(r,{quotesJson:JSON.stringify(q.filter((_,n)=>n!==i))});await load();detail(rows.find(x=>x.id===r.id))})}
function quoteForm(r,i){const q=quotes(r),x=i==null?{}:q[i],box=document.querySelector('#mp-qform');box.innerHTML='<section class="mpq-quote-editor"><h4>'+(i==null?'Adicionar':'Editar')+' cotação</h4><form id="mpqf"><div class="maintenance-fields"><label>Fornecedor<input name="supplier" required value="'+esc(x.supplier||'')+'"></label><label>Valor total (R$)<input name="amount" required value="'+esc(x.amount||'')+'"></label><label>Prazo de entrega<input name="delivery" placeholder="Ex.: 7 dias" value="'+esc(x.delivery||'')+'"></label><label>Condição de pagamento<input name="payment" placeholder="Ex.: 28/56/84 dias" value="'+esc(x.payment||'')+'"></label></div><label>Observação<input name="notes" value="'+esc(x.notes||'')+'"></label><button>Salvar cotação</button> <button type="button" id="mpq-cancel">Cancelar</button></form></section>';box.scrollIntoView({behavior:'smooth',block:'nearest'});document.querySelector('#mpq-cancel').onclick=()=>box.innerHTML='';document.querySelector('#mpqf').onsubmit=async e=>{e.preventDefault();const v={kind:'quote',...Object.fromEntries(new FormData(e.target))};const next=[...q];if(i==null)next.push(v);else next[i]=v;await save(r,{status:r.status==='Solicitado'?'Em cotação':r.status,quotesJson:JSON.stringify(next)});await load();detail(rows.find(y=>y.id===r.id))}}
load().catch(e=>root.innerHTML='<section class="panel"><p>Erro ao carregar Cotações de MP: '+esc(e.message)+'</p></section>');
